import {progressStorage,logActivity} from './activity.js';
import {lessons as basicLessons} from './lessons.js';
import {toyProject,toyGeometry,toySpots} from './project.js';
import {extraProjects,projectCatalog,extraGeometry,extraSpots} from './projects-extra.js';
import {planetaryProject,planetaryCatalog,planetaryGeometry,planetarySpots,planetaryId,foundationIds,foundationsComplete} from './project-planetary.js';
const baseProjects=[toyProject,...extraProjects];
import {gearProject,gearGeometry,gearSpots} from './gear-project.js';
const projects=[...baseProjects,gearProject,planetaryProject];
projectCatalog[planetaryId]=planetaryCatalog;
const lessons=[...projects,...basicLessons];
import {sources,chapters} from './reference.js';
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};try{saved=JSON.parse(progressStorage.getItem('fusion-click-v1')||'{}')}catch{}
let done=new Set(Array.isArray(saved.done)?saved.done:[]),li=Math.max(0,lessons.findIndex(x=>x.id===saved.lesson)),si=0,showHint=true,fit=false,skipped=false;
let projectProgress={};try{projectProgress=JSON.parse(progressStorage.getItem('fusion-projects-v2')||'{}')||{};const old=JSON.parse(progressStorage.getItem('fusion-project-v1')||'null');if(old&&!projectProgress[toyProject.id])projectProgress[toyProject.id]=old;}catch{}
const progressFor=l=>projectProgress[l.id];
const isComplete=p=>done.has(p.id)||!!(progressFor(p)&&!progressFor(p).skipped&&Number(progressFor(p).step)>=p.steps.length);
const isUnlocked=l=>!l.requires||foundationsComplete(done,projectProgress,baseProjects);
if(!isUnlocked(lessons[li]))li=0;
if(lessons[li].project&&progressFor(lessons[li])){si=Math.max(0,Math.min(lessons[li].steps.length,Number(progressFor(lessons[li]).step)||0));skipped=!!progressFor(lessons[li]).skipped;}
let values={...(progressFor(lessons[li])?.names??{})};const current=()=>lessons[li];const step=()=>current().steps[si];
function isNameField(key){return key==='filename'||/(^|-)name$/.test(key);}
function isNameStep(st){return st?.value!==undefined&&isNameField(st.target);}
function retainedNames(){return Object.fromEntries(Object.entries(values).filter(([key,value])=>isNameField(key)&&typeof value==='string'));}
function documentName(u){const name=values['toy-name']??values['new-name'];return u.project&&u.docName!=='Untitled'&&name?name+' v1':u.docName;}
function persist(){try{if(current().project){projectProgress[current().id]={step:si,skipped,names:retainedNames()};progressStorage.setItem('fusion-projects-v2',JSON.stringify(projectProgress));}progressStorage.setItem('fusion-click-v1',JSON.stringify({done:[...done],lesson:current().id}))}catch{}}
function btn(key,text,cls='',title=''){return `<button type="button" data-key="${key}" class="${cls}"${title?` title="${esc(title)}" aria-label="${esc(title)}"`:''}>${text}</button>`}
function input(key,label,value=''){
 const naming=isNameField(key),activeName=naming&&isNameStep(step())&&step().target===key;
 const shown=key==='toy-location'&&value==='Fusion Practice'?(values['toy-project-name']??value):(values[key]??value);
 return `<div class="dialog-field"><label for="f-${key}">${label}</label><input id="f-${key}" data-key="${key}" aria-label="${label}" autocomplete="off" spellcheck="false"${naming?' dir="auto" enterkeyhint="done"':''} value="${esc(shown)}"></div>${activeName?'<div class="name-confirm-row" dir="rtl"><button type="button" data-confirm-name="'+key+'">אישור השם ←</button></div>':''}`;
}
function select(key,label,options,initial){return `<div class="dialog-field"><label for="f-${key}">${label}</label><select id="f-${key}" data-key="${key}" aria-label="${label}">${options.map(o=>`<option${o===(values[key]??initial)?' selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
const val=(label,v)=>`<div class="dialog-field"><label>${label}</label><span class="value ${v==='Select'||v.includes('selected')?'selection-value':''} ${v==='✓'?'checkbox-value':''}">${v==='✓'?'<span class="native-check">✓</span>':v}${['Profile Plane','One Side','Inside','Constant'].includes(v)?'<span class="field-caret">⌄</span>':''}</span></div>`;
function dialog(name,u){
 let body='',title=name.toUpperCase(),large=false,ok='ok',okLabel='OK';
 switch(name){
 case 'new': title='What do you want to design?';large=true;body=`<div class="new-design-layout"><div class="design-options">${[['part','Part Design','body'],['assembly-option','Assembly Design','component'],['hybrid-option','Hybrid Design','combine'],['drawing-option','Drawing','table'],['electronics-option','Electronics Design','pattern'],['library-option','Electronics Library','configure']].map(([k,label,ic])=>btn(k,cadIcon(ic)+`<span>${label}</span>`,(u.selected==='hybrid'?k==='hybrid-option':k==='part'&&u.selected)?'selected':'')).join('')}</div><div class="design-info"><h3>${u.designType==='hybrid'?'Hybrid Design':'Part Design'}</h3><p>${u.designType==='hybrid'?'Create components, bodies and assembly relationships.':'Create sketches and bodies to model a single component.'}</p>${val('Type',cadIcon('body'))}${val('Unit System','Millimeter (mm)')}</div></div>`;ok='create-design';okLabel='Create New';break;
 case 'units':title='CHANGE ACTIVE UNITS';body=select('unit-select','Unit Type',['— Select —','Millimeter','Centimeter','Meter','Inch'],'— Select —');break;
 case 'extrude':case 'cut':title='EXTRUDE';body=`<div class="dialog-field"><label>Type</label><div class="type-options"><span class="type-active">${cadIcon('extrude')}</span><img class="cad-icon" src="icons/extrude-thin.png" alt="Thin Extrude"></div></div>`+val('Profiles',u.shape==='profile'?'Select':'1 selected')+val('Start','Profile Plane')+val('Direction','One Side')+select('extent','Extent Type',['Distance','All','To Object'],'Distance')+(name==='extrude'?input('distance','Distance','0 mm'):val('Distance','All'))+val('Taper Angle','0 deg')+select('operation','Operation',['New Body','Join','Cut','Intersect'],'Join');break;
 case 'fillet':title='FILLET';body=val('Edges',u.shape==='plate'?'Select':'1 selected')+input('radius','Radius','0 mm')+val('Radius Type','Constant')+val('Tangent Chain','✓');break;
 case 'shell':title='SHELL';body=val('Faces / Body',u.shape==='plate'?'Select':'1 selected')+input('thickness','Inside Thickness','0 mm')+val('Direction','Inside');break;
 case 'parameters':title='PARAMETERS';large=true;body=`<div>User Parameters ${btn('add-param','+','add-param','Add User Parameter')}</div><table class="param-table"><tr><th>Name</th><th>Unit</th><th>Expression</th><th>Value</th></tr>${u.paramAdded?`<tr><td>${esc(values['param-name']??'thickness')}</td><td>mm</td><td>8</td><td>8.00</td></tr>`:'<tr><td colspan="4">No user parameters</td></tr>'}</table>`;ok='close-params';okLabel='Close';break;
 case 'add-param':title='ADD USER PARAMETER';body=input('param-name','Name','')+val('Unit','mm')+input('expression','Expression','')+val('Comment','');break;
 case 'pattern':title='RECTANGULAR PATTERN';body=select('object-type','Object Type',['Bodies','Faces','Features','Components'],'Bodies')+val('Objects',si>=5?'1 selected':'Select')+val('Axes',si>=6?'1 selected':'Select')+select('distribution','Distribution',['Extent','Spacing'],'Extent')+input('quantity','Quantity','2')+input('spacing','Distance','0 mm')+val('Direction','One Direction');break;
 case 'measure':title='MEASURE';body=val('Selection',u.measured?'1 edge':'Select')+(u.measured?val('Length','80.00 mm'):val('Result','—'))+val('Precision','0.00');ok='close-measure';okLabel='Close';break;
 case 'section':title='SECTION ANALYSIS';body=val('Face',si>=3?'1 selected':'Select')+input('offset','Distance','0 mm')+val('Angle','0 deg')+val('Show Hatch','✓');break;
 case 'joint':title='JOINT';body=`<div class="dialog-tabs">${btn('position','Position')}${btn('motion','Motion')}</div>`+(u.motion?select('joint-type','Type',['Rigid','Revolute','Slider','Cylindrical'],'Rigid')+val('Rotate','Z Axis'):val('Component 1',si>=3?'TrainingPin:1':'Select')+val('Component 2',si>=4?'TrainingPlate:1':'Select')+val('Offset','0 mm'));break;
 case 'export':title='EXPORT';body=input('filename','Name','Untitled')+select('format','Type',['Fusion Files','STEP Files','IGES Files'],'Fusion Files')+val('Location','Local folder · demo');ok='do-export';okLabel='Export';break;
 }
 return `<div class="fusion-dialog ${large?'large':''} dialog-${name}"><div class="dialog-title"><span>${title}</span><span>⌄</span></div><div class="dialog-body">${body}</div><div class="dialog-actions">${name==='new'?btn('cancel','Cancel')+btn(ok,okLabel):btn(ok,okLabel)+btn('cancel','Cancel')}</div></div>`;
}
function projectDialog(u){const fields=u.projectFields??[];return `<div class="fusion-dialog project-command"><div class="dialog-title"><span>${esc(u.projectDialog)}</span><span>⌄</span></div><div class="dialog-body">${fields.map(f=>f.readonly?val(f.label,f.value):f.action?btn(f.key,f.label,'project-small-action'):f.options?select(f.key,f.label,f.options,f.value):input(f.key,f.label,f.value)).join('')}${u.projectDialog==='SAVE'?btn('project-new-folder','New Project','project-small-action'):''}${u.projectDialog==='OFFSET'?btn('toy-offset-flip','⇄ Flip','project-small-action'):''}</div><div class="dialog-actions">${btn('project-ok',u.projectDialog==='SAVE'?'Save':u.projectDialog==='SCRIPTS AND ADD-INS'?'Run':'OK')}${btn('cancel','Cancel')}</div></div>`;}
