function applyFit(){const vp=$('#viewport'),f=$('#fusion');if(fit){const scale=Math.min(1,vp.clientWidth/1060);f.style.transform=`scale(${scale})`;f.style.marginBottom=`${610*(scale-1)}px`;f.style.marginRight=`${1060*(scale-1)}px`;vp.style.height=`${610*scale+2}px`;vp.style.overflow='hidden';}else{f.style.transform='';f.style.marginBottom='';f.style.marginRight='';vp.style.height='';vp.style.overflow='auto';}$('#fit').textContent=fit?'גודל מקורי':'הצג מסך מלא';$('#fit').setAttribute('aria-pressed',String(fit));}
function target(){return step()?$$('#fusion [data-key]').find(e=>e.dataset.key===step().target&&e.closest('.dropdown,.fusion-dialog,.inline-dimensions,.timeline,.hotspot'))??$$('#fusion [data-key]').find(e=>e.dataset.key===step().target):null}
function highlight(){ $$('.highlight').forEach(e=>e.classList.remove('highlight'));$('.target-cursor')?.remove();if(!showHint)return;const el=target();if(!el)return;el.classList.add('highlight');const box=el.getBoundingClientRect(),f=$('#fusion').getBoundingClientRect(),scale=f.width/1060;if(!scale)return;const cursor=document.createElement('div');cursor.className='target-cursor';cursor.style.left=Math.min(1013,(box.right-f.left)/scale-5)+'px';cursor.style.top=Math.min(560,(box.bottom-f.top)/scale-7)+'px';$('#fusion').append(cursor);}
function focusTarget(){const t=target();if(!t)return;if(isNameStep(step())&&t.matches('input')&&document.activeElement!==t){t.focus({preventScroll:true});t.select();}const vp=$('#viewport');if(!fit){const r=t.getBoundingClientRect(),v=vp.getBoundingClientRect();vp.scrollTo({left:vp.scrollLeft+r.left-v.left-v.width/2+r.width/2,top:vp.scrollTop+r.top-v.top-v.height/2+r.height/2,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});} }
function render(){const l=current(),st=step();$('#category').textContent=l.category;$('#lesson-title').textContent=l.title;$('#lesson-intro').textContent=l.intro;$('#step-track').classList.toggle('project-track',!!l.project);$('#step-track').innerHTML=l.steps.map((x,i)=>`<span class="${i<si?'past':i===si?'current':''}" title="שלב ${i+1}"></span>`).join('');$('#step-count').textContent=st?`שלב ${si+1} מתוך ${l.steps.length}`:'התרגול הושלם';$('#instruction').innerHTML=st?`<span class="step-number">${si+1}</span><h3>${esc(st.title)}</h3><p>${esc(isNameStep(st)?`הקלד כל שם שנוח לך ולחץ על ״אישור השם״ או Enter. אין צורך להתאים לשם שבדוגמה (${st.value}).`:st.body.replace('Fusion Practice',()=>values['toy-project-name']??'Fusion Practice'))}</p>`:`<span class="step-number">✓</span><h3>הפעולה בידיים שלך.</h3><p>${esc(l.id==='parameters'?l.result.replaceAll('thickness',()=>values['param-name']??'thickness'):l.result)}</p>${skipped?'<p class="skip-note">דילגת על שלב אחד או יותר. אפשר לחזור ולתרגל אותם.</p>':''}<button class="primary" id="next-lesson">${l.project?(l.id!==planetaryId&&isUnlocked(planetaryProject)?'לפרויקט המנגנון הפלנטרי ←':'לבחירת פרויקט ←'):li<lessons.length-1?'לתרגול הבא ←':'לכל התרגולים ←'}</button>`;$('#back').disabled=si===0;$('#skip').disabled=!st;$('#hint').disabled=!st;$('#lesson-source').href=sources[l.refs[0]].url;$('#lesson-source').textContent=`${sources[l.refs[0]].title} ↗`;$('#overall').textContent=`${done.size} / ${lessons.length}`;$('#overall-bar').style.width=`${done.size/lessons.length*100}%`;$('#feedback').textContent='';renderProjectUI(l,st);renderSim();if(st&&!$('#learning-page').hidden)setTimeout(focusTarget,90);$('#next-lesson')?.addEventListener('click',()=>l.project?(l.id!==planetaryId&&isUnlocked(planetaryProject)?start(projects.indexOf(planetaryProject),true):openProjects()):li<lessons.length-1?start(li+1):openLessons());persist();}
function start(i,resume=false){if(!lessons[i]||!isUnlocked(lessons[i])){openProjects();return;}showLearning();li=i;const progress=progressFor(current());si=resume&&progress?Math.max(0,Math.min(current().steps.length,Number(progress.step)||0)):0;values=resume&&progress?{...progress.names}:{};skipped=resume&&progress?!!progress.skipped:false;showHint=!$('#practice').checked;$('#drawer').close();render();logActivity(resume?'project_resume':'project_start',current().id,Math.min(si+1,current().steps.length));}
function advance(kind='step_complete'){if(!step())return;logActivity(kind,current().id,si+1);si++;if(current().project)values=retainedNames();showHint=!$('#practice').checked;if(si===current().steps.length){if(!skipped){done.add(current().id);logActivity('project_complete',current().id,si);}}render();}
function acknowledge(msg){$('#feedback').textContent=msg;}
function confirmName(field){const st=step();if(!field||!isNameStep(st)||field.dataset.key!==st.target)return;const name=field.value.trim();if(!name){acknowledge('אפשר לבחור כל שם. הקלד שם כדי להמשיך.');field.focus();return;}values[st.target]=name;advance();}
$('#fusion').addEventListener('click',e=>{const animation=e.target.closest('[data-animation-toggle]');if(animation){const paused=$('#fusion .pg-animated').classList.toggle('pg-paused');animation.setAttribute('aria-pressed',String(paused));animation.textContent=paused?'הפעלת ההנפשה ▶':'השהיית ההנפשה ⏸';return;}const confirm=e.target.closest('button[data-confirm-name]');if(confirm){confirmName($('#f-'+confirm.dataset.confirmName));return;}const b=e.target.closest('button[data-key]');if(!b||!step())return;if(b.dataset.key===step().target){if(step().value!==undefined||step().select!==undefined)return;advance();}else{acknowledge('זה לא הכלי של השלב הנוכחי. אפשר ללחוץ על ״איפה ללחוץ?״.');}});
$('#fusion').addEventListener('input',e=>{if(e.target.matches('input[data-key]'))values[e.target.dataset.key]=e.target.value;});
function norm(v){return String(v).trim().toLowerCase().replace(/\s*mm$/,'').replace(',','.');}
$('#fusion').addEventListener('keydown',e=>{if(e.key!=='Enter'||e.isComposing||!e.target.matches('input[data-key]')||!step())return;e.preventDefault();const st=step();if(e.target.dataset.key!==st.target)return;if(isNameStep(st)){confirmName(e.target);return;}if(norm(e.target.value)===norm(st.value)){values[st.target]=e.target.value;advance();}else acknowledge(`בשדה הזה יש להזין ${st.value}, ואז להקיש Enter.`);});
$('#fusion').addEventListener('change',e=>{if(!e.target.matches('select[data-key]')||!step())return;const st=step();values[e.target.dataset.key]=e.target.value;if(e.target.dataset.key===st.target){if(e.target.value===st.select)advance();else acknowledge(`בחר ${st.select} כדי להמשיך.`);}});
$('#back').onclick=()=>{if(si>0){si--;logActivity('step_back',current().id,si+1);if(current().project)values=retainedNames();showHint=!$('#practice').checked;render();}};
$('#skip').onclick=()=>{skipped=true;advance('step_skip');};$('#hint').onclick=()=>{logActivity('hint',current().id,si+1);showHint=true;highlight();focusTarget();};$('#practice').onchange=()=>{showHint=!$('#practice').checked;highlight();};$('#focus').onclick=focusTarget;$('#fit').onclick=()=>{fit=!fit;applyFit();highlight();};$('#restart').onclick=()=>start(li);window.addEventListener('resize',()=>{applyFit();highlight();});
function drawer(title,html){$('.navigation-more')?.removeAttribute('open');$('#drawer-title').textContent=title;$('#drawer-content').innerHTML=html;if(!$('#drawer').open)$('#drawer').showModal();$('#drawer').scrollTop=0;}
function openLessons(){drawer('בוחרים מה לתרגל',`<p class="drawer-intro">שלושה פרויקטי בסיס, גלגל שיניים, פרויקט המשך ו־${basicLessons.length} תרגולים נקודתיים. הפרויקט בונה חלק מתחילתו; התרגולים הנקודתיים נפתחים ממצב מוכן. ההתקדמות נשמרת בדפדפן הזה.</p><div class="lesson-grid">${lessons.map((l,i)=>`<button class="lesson-card ${i===li?'active':''}" data-lesson="${i}" ${!isUnlocked(l)?'disabled aria-label="פרויקט נעול: יש להשלים את שלושת פרויקטי הבסיס"':''}><span class="lesson-icon">${l.icon}</span><span><b>${esc(l.title)}</b><small>${l.category} · ${l.steps.length} צעדים · ${l.time}</small></span><span class="lesson-status">${!isUnlocked(l)?'נעול':done.has(l.id)?'✓':'←'}</span></button>`).join('')}</div>`);$$('[data-lesson]').forEach(b=>b.onclick=()=>start(Number(b.dataset.lesson)));}
function referenceItems(query=''){const rows=chapters.flatMap(c=>c.rows.map(r=>({...r,chapter:c.name}))).filter(r=>`${r.action} ${r.cmd} ${r.chapter}`.toLowerCase().includes(query.toLowerCase()));return rows.length?rows.map(r=>`<details><summary>${r.id}. ${esc(r.action)}<small>${esc(r.cmd)}</small></summary><p><b>לפני שמתחילים:</b> ${esc(r.before)}</p><ol>${r.steps.split('\n').map(x=>`<li>${esc(x.replace(/^\d+\.\s*/,''))}</li>`).join('')}</ol><p class="check"><b>בדיקת הצלחה:</b> ${esc(r.result)}</p><p><b>שים לב:</b> ${esc(r.pitfall)}</p><div class="source-links">${r.refs.map(id=>`<a href="${esc(sources[id].url)}" target="_blank" rel="noopener">${esc(sources[id].title)} ↗</a>`).join('')}</div></details>`).join(''):'<p class="drawer-intro">לא נמצאה פעולה. נסה שם כלי באנגלית או מילה אחרת בעברית.</p>';}
function openReference(){drawer('מדריך 76 הפעולות',`<p class="drawer-intro">כל מדריך הפעולות מהאקסל, כעת לחיפוש וקריאה. ${lessons.length} מהנושאים זמינים גם כתרגול לחיצות; הרשימה כאן כוללת את ההדרכה המילולית המלאה.</p><input id="search" class="reference-search" type="search" placeholder="חיפוש פעולה, למשל: חור, Joint, סקיצה…" aria-label="חיפוש פעולה"><div class="reference-list" id="reference-list">${referenceItems()}</div>`);$('#search').oninput=e=>$('#reference-list').innerHTML=referenceItems(e.target.value);}
function openSources(){drawer('מקורות ושיטת העבודה',`<div class="source-note"><b>ממשק מדומה, הוראות מבוססות מקורות.</b><br>פרויקט גלגל השיניים מבוסס על שיטת Kevin McAleer מ־2025 ותיעוד Autodesk מ־2026, עם מידות וחורי תרגול שנבחרו כאן. פרויקטי הבסיס מבוססים על תמלילי Product Design Online במהדורת 2026. פרויקט המנגנון הפלנטרי הוא עיבוד לסרטון RELUvance מ־2019, לפי פרקי הסרטון ופריימים שנבדקו, יחד עם תיעוד Autodesk שנבדק ב־17.10.2026. מידות העזר לנשא ולצירים נבחרו לתרגול; יחסי התנועה חושבו בנפרד. פריסת הממשק נבנתה בהשראת רפרנסים של Fusion. האייקונים, הגאומטריה וחלק מהחלונות פושטו ללמידה, ואינם צילום מסך או העתק מדויק של כל גרסה. לא בוצעה הרצה בהתקנת Fusion ולא אומת דירוג ביקורות לשיעורים עצמם.</div><h3>רפרנס YouTube: היכרות עם הממשק</h3><p class="drawer-intro">שיעור 1 של Kevin Kennedy / Product Design Online, מהדורת 2026. הווידאו הוא המקור המקורי; הדמיית הלחיצות נבנתה בנפרד. פרויקט הלבנה משתמש במידות שבסרטון. בתרגולים הנקודתיים המידות נבחרו בנפרד.</p><iframe class="video-frame" src="https://www.youtube-nocookie.com/embed/4G2E_DqQteM" title="PDO Fusion 2026 Day 1" loading="lazy" allow="fullscreen; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><p class="drawer-intro"><a href="https://www.youtube.com/watch?v=4G2E_DqQteM" target="_blank" rel="noopener">פתיחת הסרטון ב־YouTube ↗</a></p><h3>מקורות לתרגולי הלחיצה</h3>${[...new Set(lessons.flatMap(l=>l.refs))].map(id=>`<div class="source-row"><a href="${esc(sources[id].url)}" target="_blank" rel="noopener">${esc(sources[id].title)} ↗</a><small>${esc(sources[id].version)} · ${esc(sources[id].focus)}</small></div>`).join('')}<div class="source-row"><a href="https://forums.autodesk.com/t5/fusion-foro-en-espanol/what-s-new-novedades-de-fusion-2026/td-p/13986692" target="_blank" rel="noopener">רפרנס למראה מסך בחירת התכנון — Autodesk Community 2026 ↗</a></div>`);}
$('#new-project-button').onclick=openProjects;$('#lessons-button').onclick=openLessons;$('#choose').onclick=openLessons;$('#reference-button').onclick=openReference;$('#sources-button').onclick=openSources;$('#close-drawer').onclick=()=>$('#drawer').close();$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#reset-progress').onclick=()=>{drawer('איפוס התקדמות',`<p class="drawer-intro">למחוק את סימוני ההשלמה בדפדפן הזה? תוכן המדריך יישאר זמין.</p><button class="primary" id="confirm-reset">כן, איפוס ההתקדמות</button>`);$('#confirm-reset').onclick=()=>{done.clear();projectProgress={};try{progressStorage.removeItem('fusion-project-v1');progressStorage.removeItem('fusion-projects-v2')}catch{}start(0);};};render();

function renderProjectUI(l,st){
 const panel=$('#project-context');panel.hidden=!l.project;
 if(l.project){const phaseIndex=st?l.phases.findIndex(p=>p.title===st.phase):l.phases.length-1;panel.innerHTML=`<div class="project-phase"><span>פרק ${phaseIndex+1} / ${l.phases.length}</span><strong>${esc(st?.phase??'הפרויקט הושלם')}</strong><span>${Math.round(si/l.steps.length*100)}%</span></div><div class="project-phase-dots">${l.phases.map((p,i)=>`<span class="${i<=phaseIndex?'reached':''}" title="${esc(p.title)}"></span>`).join('')}</div><a href="${projectCatalog[l.id].video}${l.id===planetaryId?'&t='+(l.phases[phaseIndex]?.time??0):''}" target="_blank" rel="noopener">לסרטון הפרויקט · ${esc(projectCatalog[l.id].sourceLabel??'PDO 2026')} ↗</a>`;}
 $('.context-note').innerHTML=l.id===planetaryId?'<strong>מהמודל למנגנון בתנועה.</strong><span>עיבוד מודרך לסרטון מ־2019, עם פקודות עדכניות. מידות עזר נבחרו לתרגול. השיניים והחלונות הם המחשה; לא נוצר כאן קובץ CAD.</span>':l.project?'<strong>אותו חלק, מהתחלה עד הסוף.</strong><span>המודל מתקדם עם השלבים. ההתקדמות נשמרת בדפדפן, והבחירות והממדים מוצגים כהדמיה לימודית.</span>':'<strong>לומדים את הממשק, לא מנחשים.</strong><span>כל תרגול נפתח עם מצב התחלתי מוכן. המודל והחלונות הם המחשה לימודית; ייתכנו הבדלים בין גרסאות ורישיונות.</span>';
 if(l.project){$('#step-count').textContent=st?`צעד ${si+1} מתוך ${l.steps.length}`:'הפרויקט הושלם';$('#lesson-source').href=projectCatalog[l.id].video+(l.id===planetaryId?'&t='+(l.phases.find(p=>p.title===st?.phase)?.time??0):'');$('#lesson-source').textContent='סרטון הפרויקט ב־YouTube ↗';}
}
function projectCard(p,i){
 const m=projectCatalog[p.id],pr=progressFor(p),n=Math.max(0,Math.min(p.steps.length,Number(pr?.step)||0)),unlocked=isUnlocked(p),completed=isComplete(p),resume=n>0&&n<p.steps.length;
 return `<article class="project-option ${!unlocked?'project-locked':''}"><div class="option-art option-${i}">${p.id===planetaryId?planetaryGeometry('planet-carrier'):geometry(p.end.shape)}<span>${completed?'✓ הושלם':m.badge}</span></div><div class="option-content"><span class="eyebrow">${m.sourceLabel??'PDO 2026 · DAY '+(i+1)}</span><h3>${esc(p.title)}</h3><strong class="option-focus">${m.focus}</strong><details class="project-more"><summary>מה לומדים?</summary><p>${m.description}</p><div class="project-chips">${m.tools.map(t=>'<span>'+t+'</span>').join('')}</div><p class="option-fit">${m.fit}</p></details><small>${p.phases.length} פרקים · ${p.steps.length} צעדים · ${p.time}</small>${n>0?'<div class="option-progress"><span style="width:'+100*n/p.steps.length+'%"></span></div><small>'+(completed?'הפרויקט הושלם':n===p.steps.length?'המסלול הסתיים עם דילוגים — נדרש תרגול מלא':'הגעת לצעד '+(n+1))+'</small>':''}${p.id===planetaryId?'<div class="unlock-checklist"><strong><bdi dir="ltr">'+baseProjects.filter(isComplete).length+' / 3</bdi> פרויקטי בסיס הושלמו</strong>'+baseProjects.map(x=>'<span class="'+(isComplete(x)?'completed':'')+'">'+(isComplete(x)?'✓':'○')+' '+esc(x.title)+'</span>').join('')+'</div>':''}<button class="primary" data-project="${i}" data-resume="${resume}" ${!unlocked?'disabled':''}>${!unlocked?'נפתח אחרי 3 פרויקטי הבסיס':resume?'ממשיכים מהמקום שלי ←':completed?'מתרגלים שוב ←':'מתחילים בפרויקט ←'}</button>${resume&&unlocked?'<button class="restart-project" data-project="'+i+'" data-resume="false">התחלה מחדש</button>':''}<a class="project-video" href="${m.video}" target="_blank" rel="noopener">המדריך המקורי ב־YouTube ↗</a></div></article>`;
}
function openProjects(){
 drawer('מסלול הפרויקטים',`<p class="drawer-intro">בחר פרויקט והמשך בקצב שלך. ההתקדמות נשמרת אוטומטית.</p><h3 class="path-heading">במה נתחיל?</h3><div class="project-options">${[...baseProjects,gearProject].map(projectCard).join('')}</div><h3 class="path-heading next-project-heading">בהמשך — מנגנון פלנטרי</h3><div class="advanced-project">${projectCard(planetaryProject,projects.indexOf(planetaryProject))}</div><p class="drawer-intro project-note">פרויקט נחשב כהושלם לאחר ביצוע כל צעדיו ללא דילוג. אם דילגת, אפשר להתחיל מחדש ולתרגל אותו במלואו. הסימון נשמר בדפדפן הזה. הסרטונים המלאים זמינים גם לפני פתיחת התרגול; ההדמיה אינה יוצרת קובץ CAD.</p>`);
 $$('[data-project]').forEach(b=>b.onclick=()=>start(Number(b.dataset.project),b.dataset.resume==='true'));
}


// Learning-shell navigation. Lesson content and Fusion geometry remain independent.
function shellCurrent(page){
 $('#home-button').setAttribute('aria-current',page==='home'?'page':'false');
 $('.navigation-more')?.removeAttribute('open');
}
function showLearning(){
 $('#home-page').hidden=true;$('#learning-page').hidden=false;shellCurrent('learn');$('.skip-link').setAttribute('href','#lesson-title');
 if(location.hash!=='#learn')history.pushState(null,'','#learn');
}
function homePreview(p,i){
 const boxes=['100 105 390 250','110 30 300 340','110 30 300 340','100 50 320 340'];
 return geometry(p.end.shape).replace(/viewBox="[^"]*"/,`viewBox="${boxes[i]}"`).replace('preserveAspectRatio="none"','preserveAspectRatio="xMidYMid meet"').replace(/id="([^"]+)"/g,`id="home-${i}-$1"`).replace(/url\(#([^)]+)\)/g,`url(#home-${i}-$1)`);
}
function homeProjectCard(p,i){
 const m=projectCatalog[p.id],pr=progressFor(p),n=Math.max(0,Math.min(p.steps.length,Number(pr?.step)||0)),resume=n>0&&n<p.steps.length;
 return `<article class="home-project"><div class="home-project-art home-art-${i}" aria-hidden="true">${homePreview(p,i)}<span class="home-card-number">0${i+1}</span></div><div class="home-project-body"><span class="home-project-meta">${p.phases.length} פרקים · ${p.steps.length} צעדים</span><h3>${esc(p.title)}</h3><p>${esc(m.focus)}</p><div class="home-card-bottom"><span>${isComplete(p)?'✓ הושלם':resume?'צעד '+(n+1)+' מתוך '+p.steps.length:m.badge}</span><button data-home-project="${i}" data-resume="${resume}" aria-label="${resume?'המשך':'התחל'} ${esc(p.title)}">${resume?'להמשיך':'מתחילים'} <span aria-hidden="true">←</span></button></div></div></article>`;
}
function refreshHome(){
 $('#home-project-grid').innerHTML=[...baseProjects,gearProject].map(homeProjectCard).join('');
 $$('[data-home-project]').forEach(b=>b.onclick=()=>{start(Number(b.dataset.homeProject),b.dataset.resume==='true');$('#lesson-title').focus({preventScroll:true});window.scrollTo(0,0);});
 const inProgress=si>0&&si<current().steps.length;
 $('#home-resume-panel').hidden=!inProgress;
 $('#resume-title').textContent=current().title;$('#resume-detail').textContent=`צעד ${si+1} מתוך ${current().steps.length} · ההתקדמות שלך שמורה כאן`;
}
function showHome(updateHistory=true){
 $('#drawer').close();$('#home-page').hidden=false;$('#learning-page').hidden=true;shellCurrent('home');$('.skip-link').setAttribute('href','#main-content');refreshHome();
 if(updateHistory&&location.hash!=='#home'){history.pushState(null,'','#home');logActivity('home');}
}
function scrollHome(id){showHome();const el=document.getElementById(id);el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});el.querySelector('h2')?.focus({preventScroll:true});}
function openHow(){drawer('כך מתרגלים כאן',`<div class="onboarding-guide"><p class="drawer-intro">ההוראה ליד המסך אומרת מה לעשות עכשיו. מבצעים אותה בתוך ההדמיה, והצעד הבא נפתח אוטומטית.</p><ol><li><b>לחיצה:</b> בוחרים את הכפתור או האזור שמופיעים בהוראה.</li><li><b>הזנת ערך:</b> מקלידים את המספר ומקישים Enter. בשדה שם אפשר לבחור שם משלך ולאשר.</li><li><b>צריכים רמז?</b> ״איפה ללחוץ?״ מחזיר את ההדגשה; ״מיקוד בכפתור״ גולל לאזור הנכון.</li><li><b>בקצב שלך:</b> ״חזרה״ חוזר צעד אחד. ״אפשרויות תרגול״ כולל דילוג, התחלה מחדש ותרגול בלי הדגשה.</li></ol><div class="onboarding-note">כדי להשלים פרויקט ולפתוח את פרויקט ההמשך, מבצעים את כל הצעדים ללא דילוג. התקדמות נשמרת בדפדפן הזה. בטלפון אפשר לגלול לצדדים בתוך מסך Fusion.</div><button id="help-done" class="studio-primary">הבנתי, אפשר להתחיל ←</button></div>`);$('#help-done').onclick=()=>$('#drawer').close();}
$('#home-button').onclick=()=>{showHome();window.scrollTo(0,0);$('#home-title').focus?.({preventScroll:true});};
$('.brand').addEventListener('click',e=>{e.preventDefault();showHome();window.scrollTo(0,0);});
$('#learning-home').onclick=()=>{showHome();window.scrollTo(0,0);};
$('#home-start').onclick=()=>scrollHome('home-projects');$('#home-how').onclick=()=>scrollHome('how-it-works');
$('#home-all-projects').onclick=openProjects;$('#home-tools').onclick=openLessons;
$('#how-button').onclick=openHow;$('#learning-help').onclick=openHow;
$('#home-resume').onclick=()=>{showLearning();render();logActivity('project_resume',current().id,Math.min(si+1,current().steps.length));$('#lesson-title').focus({preventScroll:true});window.scrollTo(0,0);};
window.addEventListener('popstate',()=>{if(location.hash==='#learn'){showLearning();render();}else showHome(false);});
if(location.hash==='#learn'){showLearning();render();}else showHome(false);
